import bpy, math
from mathutils import Vector
def mat_by(n): return bpy.data.materials[n]
YEL=mat_by('YellowPlastic'); BLK=mat_by('BlackPlastic'); WHT=mat_by('White')
YEL.node_tree.nodes['Principled BSDF'].inputs['Base Color'].default_value=(1.0,0.72,0.0,1)
bpy.data.worlds['World'].node_tree.nodes['Background'].inputs[1].default_value=0.35

# delete feet, soles, foot grooves, neckgap
to_del=[]
for o in list(bpy.data.objects):
    mats=[m.name for m in o.data.materials] if hasattr(o.data,'materials') else []
    if o.name.startswith(('Foot','Sole','NeckGap')) or any(m.startswith('fg') for m in mats):
        to_del.append(o)
for o in to_del: bpy.data.objects.remove(o,do_unlink=True)

def assign(o,m): o.data.materials.append(m)
def smooth(o):
    for p in o.data.polygons: p.use_smooth=True

# thin neck ring
bpy.ops.mesh.primitive_cylinder_add(radius=0.875,depth=0.035,location=(0,0,1.335),vertices=64); o=bpy.context.active_object; o.name='NeckRing'; assign(o,BLK); smooth(o)

# new feet: simple ellipsoids, flattened bottom via location intersecting ground slightly
for sx in (-1,1):
