    bpy.ops.mesh.primitive_uv_sphere_add(radius=0.5,location=(sx*0.97,-0.32,0.045),segments=32,ring_count=16); s=bpy.context.active_object; s.name='Sole'; s.scale=(0.58,1.38,0.10); assign(s,BLK); smooth(s)
    # two subtle groove lines across top rear of foot using thin torus arcs: use thin boxes slightly embedded
    for k in range(2):
