import bpy, math, os
from mathutils import Vector
YEL=bpy.data.materials['YellowPlastic']; YEL.node_tree.nodes['Principled BSDF'].inputs['Base Color'].default_value=(1.0,0.68,0.0,1)
# reduce lights
for o in bpy.data.objects:
    if o.type=='LIGHT': o.data.energy*=0.55
# remove foot groove boxes (DarkBrown material cubes low)
for o in list(bpy.data.objects):
    if o.type=='MESH' and o.location.z<0.5 and any(m.name=='DarkBrown' for m in o.data.materials):
        bpy.data.objects.remove(o,do_unlink=True)
r=bpy.data.objects.get('ROBIE')
if r: r.location=(-0.18,-0.93,1.10); r.data.size=0.17

# convert curves/text to mesh for export
bpy.ops.object.select_all(action='DESELECT')
for o in bpy.data.objects:
    if o.type in ('CURVE','FONT'): o.select_set(True)
if bpy.context.selected_objects:
    bpy.context.view_layer.objects.active=bpy.context.selected_objects[0]
    bpy.ops.object.convert(target='MESH')

cam=bpy.context.scene.camera
def setcam(loc,target=(0,0,1.0)):
    cam.location=loc; cam.rotation_euler=(Vector(target)-Vector(loc)).to_track_quat('-Z','Y').to_euler()
sc=bpy.context.scene; sc.render.resolution_x=1000; sc.render.resolution_y=1000
setcam((2.6,-4.4,2.4)); sc.render.filepath='//output/robie_front34.png'; bpy.ops.render.render(write_still=True)
setcam((0,-5.2,1.5)); sc.render.filepath='//output/robie_front.png'; bpy.ops.render.render(write_still=True)
setcam((-3.0,3.8,3.2),(0,0,1.1)); sc.render.filepath='//output/robie_back_top.png'; bpy.ops.render.render(write_still=True)

# export GLB without ground/camera/lights
bpy.ops.object.select_all(action='DESELECT')
for o in bpy.data.objects:
    if o.name!='Ground' and o.type not in ('CAMERA','LIGHT'): o.select_set(True)
bpy.ops.export_scene.gltf(filepath=os.path.abspath('output/robie_banker.glb'),export_format='GLB',use_selection=True,export_draco_mesh_compression_enable=False)
# cleanup preview
try: os.remove(os.path.abspath('output/preview1.png'))
except: pass
result={'files':os.listdir(os.path.abspath('output'))}
